"""Second half of the generated R26 physical runtime C source."""
from __future__ import annotations
from .midi_68k_r26_double_impact import SaturnMidi68KR26DoubleImpactProfile
from .midi_68k_r26_physical_candidate import SATURN_MIDI_68K_R26_PHASE_DRAINING, SATURN_MIDI_68K_R26_PHASE_ERROR, SATURN_MIDI_68K_R26_PHASE_NOT_STARTED, SATURN_MIDI_68K_R26_PHASE_PASS, SATURN_MIDI_68K_R26_PHASE_PLAYING, SATURN_MIDI_68K_R26_PHASE_VERIFY_STATE, SATURN_MIDI_68K_R26_PHASE_WAIT_BOOT, SATURN_MIDI_68K_R26_VERIFY_FINAL_CONTRACT_MISMATCH

def r26_physical_runtime_lines(profile: SaturnMidi68KR26DoubleImpactProfile) -> tuple[str, ...]:
    return (f'       state->telemetry.voice_key_off_count != {profile.note_off_count}u ||', '       state->telemetry.voice_busy_count != 0u ||', '       state->telemetry.voice_held_count != 0u ||', '       state->telemetry.voice_releasing_count != 0u ||', '       state->telemetry.voice_owned_count != 0u ||', f'       state->telemetry.voice_peak_held != {profile.capacity.peak_held}u ||', f'       state->telemetry.voice_peak_owned != {profile.capacity.peak_owned}u ||', f'       state->telemetry.voice_release_cancelled < {profile.capacity.release_steal_count}u ||', '       state->telemetry.voice_last_error != 0u ||', f'       state->telemetry.player_sequence != {profile.batch_count}u ||', f'       state->telemetry.player_batch_index != {profile.batch_count}u ||', '       state->telemetry.player_complete != 1u || state->telemetry.player_error != 0u){', f'        state->telemetry.state_verify_status = {SATURN_MIDI_68K_R26_VERIFY_FINAL_CONTRACT_MISMATCH}u;', '        state->telemetry.mismatch_region = state->telemetry.state_verify_status;', '        return 0;', '    }', '    state->telemetry.state_verify_status = 1u;', '    return 1;', '}', '', 'static unsigned int srk_r26_fail(SRK_SATURN_MIDI_68K_R26_PHYSICAL_PROOF_STATE *state, unsigned short code)', '{', '    srk_r26_restore_frt(state);', f'    state->telemetry.phase = {SATURN_MIDI_68K_R26_PHASE_ERROR}u;', '    if(state->telemetry.last_error == 0u) state->telemetry.last_error = code;', '    state->runtime_status = SRK_MIDI_68K_RUNTIME_CONSUMER_ERROR;', '    return state->runtime_status;', '}', '', 'void srk_saturn_midi_68k_r26_physical_proof_reset(SRK_SATURN_MIDI_68K_R26_PHYSICAL_PROOF_STATE *state)', '{', '    unsigned short *words;', '    unsigned long count;', '    if(!state) return;', '    words = (unsigned short *)state;', '    count = (unsigned long)(sizeof(*state) / sizeof(unsigned short));', '    while(count) words[--count] = 0u;', '    state->runtime_status = SRK_MIDI_68K_RUNTIME_NOT_STARTED;', f'    state->telemetry.phase = {SATURN_MIDI_68K_R26_PHASE_NOT_STARTED}u;', '    srk_saturn_midi_r26_player_reset(&state->player);', '    srk_saturn_midi_r24_frt_reset(&state->clock);', '}', '', 'unsigned int srk_saturn_midi_68k_r26_physical_proof_begin(SRK_SATURN_MIDI_68K_R26_PHYSICAL_PROOF_STATE *state)', '{', '    const SRK_SATURN_MIDI_68K_RUNTIME_OPS *ops;', '    if(!state) return SRK_MIDI_68K_RUNTIME_NOT_STARTED;', '    if(state->attempted) return state->runtime_status;', '    state->attempted = 1u;', '    ops = srk_saturn_midi_68k_hardware_adapter_ops();', '    if(!ops || !ops->stop_sound_cpu || !ops->start_sound_cpu) return srk_r26_fail(state, 0xE401u);', '    if(!ops->stop_sound_cpu()) return srk_r26_fail(state, 0xE402u);', '    if(!srk_r26_install()) return srk_r26_fail(state, 0xE403u);', '    if(!ops->start_sound_cpu()) return srk_r26_fail(state, 0xE404u);', '    state->runtime_status = SRK_MIDI_68K_RUNTIME_RUNNING;', f'    state->telemetry.phase = {SATURN_MIDI_68K_R26_PHASE_WAIT_BOOT}u;', '    return state->runtime_status;', '}', '', 'unsigned int srk_saturn_midi_68k_r26_physical_proof_poll(SRK_SATURN_MIDI_68K_R26_PHYSICAL_PROOF_STATE *state)', '{', '    int player_result;', '    unsigned long now_us;', '    if(!state || !state->attempted) return SRK_MIDI_68K_RUNTIME_NOT_STARTED;', '    if(state->runtime_status != SRK_MIDI_68K_RUNTIME_RUNNING) return state->runtime_status;', '    state->poll_count += 1u;', '    srk_r26_capture(state);', '    if((state->telemetry.stream_flags & SRK_R26_STREAM_ERROR) != 0u ||', '       srk_r26_service(SRK_R26_LAST_ERROR_OFFSET) != 0u || state->telemetry.last_error != 0u ||', '       state->telemetry.voice_last_error != 0u || state->telemetry.voice_busy_count != 0u)', '        return srk_r26_fail(state, 0xE410u);', '', f'    if(state->telemetry.phase == {SATURN_MIDI_68K_R26_PHASE_WAIT_BOOT}u){{', '        if(srk_r26_service(SRK_R26_SERVICE_MAGIC_OFFSET) == SRK_R26_SERVICE_MAGIC &&', '           srk_r26_service(SRK_R26_SERVICE_VERSION_OFFSET) == SRK_R26_SERVICE_VERSION){', '            state->telemetry.clock_source_hz = srk_r26_select_clock(state);', '            state->original_tcr = SRK_R26_FRT_TCR;', '            state->frt_configured = 1u;', '            srk_saturn_midi_r24_frt_configure_div128();', '            srk_saturn_midi_r24_frt_reset(&state->clock);', '            srk_saturn_midi_r26_player_reset(&state->player);', '            now_us = srk_saturn_midi_r24_frt_sample_us(&state->clock, state->telemetry.clock_source_hz);', '            state->telemetry.clock_us = now_us;', '            player_result = srk_saturn_midi_r26_player_poll(&state->player, now_us);', '            if(player_result < 0) return srk_r26_fail(state, 0xE411u);', f'            state->telemetry.phase = {SATURN_MIDI_68K_R26_PHASE_PLAYING}u;', '        }', '        return state->runtime_status;', '    }', '', f'    if(state->telemetry.phase == {SATURN_MIDI_68K_R26_PHASE_PLAYING}u){{', '        now_us = srk_saturn_midi_r24_frt_sample_us(&state->clock, state->telemetry.clock_source_hz);', '        state->telemetry.clock_us = now_us;', '        player_result = srk_saturn_midi_r26_player_poll(&state->player, now_us);', '        srk_r26_capture(state);', '        if(player_result < 0 || state->player.error != 0u) return srk_r26_fail(state, 0xE412u);', '        if(now_us > SRK_R26_TIMEOUT_US && !state->player.complete) return srk_r26_fail(state, 0xE413u);', '        if(player_result == 1 || state->player.complete){', f'            state->telemetry.phase = {SATURN_MIDI_68K_R26_PHASE_DRAINING}u;', '        }', '        return state->runtime_status;', '    }', '', f'    if(state->telemetry.phase == {SATURN_MIDI_68K_R26_PHASE_DRAINING}u){{', '        now_us = srk_saturn_midi_r24_frt_sample_us(&state->clock, state->telemetry.clock_source_hz);', '        state->telemetry.clock_us = now_us;', '        srk_saturn_midi_stream_clock_publish(now_us);', '        srk_r26_capture(state);', '        if(state->telemetry.voice_held_count == 0u && state->telemetry.voice_releasing_count == 0u &&', '           state->telemetry.voice_owned_count == 0u){', f'            state->telemetry.phase = {SATURN_MIDI_68K_R26_PHASE_VERIFY_STATE}u;', '            if(!srk_r26_verify_final_state(state)) return srk_r26_fail(state, 0xE414u);', f'            state->telemetry.phase = {SATURN_MIDI_68K_R26_PHASE_PASS}u;', '            srk_r26_restore_frt(state);', '            state->runtime_status = SRK_MIDI_68K_RUNTIME_ACKNOWLEDGED;', '            return state->runtime_status;', '        }', '        if(now_us > SRK_R26_TIMEOUT_US) return srk_r26_fail(state, 0xE415u);', '        return state->runtime_status;', '    }', '    return state->runtime_status;', '}', '')
